package cn.minidayz.patcher;
import java.net.*;import java.io.*;import org.json.*;
/** OpenAI-compatible Chat Completions; no redirects, retries or remote code execution. */
public final class AiClient {
 public static String redact(String s,String key){if(key!=null&&key.length()>0)s=s.replace(key,"[REDACTED]");return s.replaceAll("(?is)-----BEGIN [^-]*PRIVATE KEY-----.*?-----END [^-]*PRIVATE KEY-----","[PRIVATE KEY REMOVED]").replaceAll("(?i)(Bearer\\s+)[A-Za-z0-9._\\-]+","$1[REDACTED]").replaceAll("(?i)((?:api[_-]?key|access[_-]?token|password|secret)\\s*[\"']?\\s*[:=]\\s*[\"']?)[^\\s\"',}]+","$1[REDACTED]").replaceAll("sk-[A-Za-z0-9_\\-]{10,}","[REDACTED]");}
 public static JSONObject call(AiSettings s,JSONArray messages,Jobs j)throws Exception{String key=s.secret();FilesEx.require(key.length()>0,"E_AI_KEY: 请在设置填写 API 密钥");HttpURLConnection c=(HttpURLConnection)new URL(ApiProtocol.endpoint(s.endpoint(),s.protocol())).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setRequestMethod("POST");c.setDoOutput(true);String protocol=ApiProtocol.mode(s.endpoint(),s.protocol());if(protocol.equals("anthropic")){c.setRequestProperty("x-api-key",key);c.setRequestProperty("anthropic-version","2023-06-01");}else c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("User-Agent","P-Patcher/1.4.0");if(new URL(s.endpoint()).getHost().equals("opencode.ai"))c.setRequestProperty("x-opencode-session",s.session());c.setRequestProperty("Content-Type","application/json");final HttpURLConnection live=c;Thread watcher=new Thread(new Runnable(){public void run(){try{while(!Thread.currentThread().isInterrupted()){if(j.cancelled()){live.disconnect();return;}Thread.sleep(200);}}catch(InterruptedException done){}}});watcher.setDaemon(true);watcher.start();try{FilesEx.check(j);JSONObject req=ApiProtocol.body(protocol,s.model(),messages,s.limit(),s.tokenField());byte[] bytes=req.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(bytes.length);OutputStream out=c.getOutputStream();try{out.write(bytes);}finally{out.close();}int code=c.getResponseCode();FilesEx.check(j);if(code<200||code>=300){InputStream err=c.getErrorStream();String body=err==null?"无错误正文":new String(FilesEx.read(err,32768),"UTF-8");throw new IOException(ApiProtocol.error(code,body,key));}InputStream in=c.getInputStream();String raw;try{raw=new String(FilesEx.read(in,1048576),"UTF-8");}finally{in.close();}JSONObject r=new JSONObject(raw);String content=ApiProtocol.text(r,protocol);FilesEx.require(content.length()<=160000,"E_AI_RESPONSE_LIMIT");return new JSONObject().put("content",redact(content,key)).put("usage",r.optJSONObject("usage")==null?new JSONObject():r.getJSONObject("usage"));}finally{watcher.interrupt();c.disconnect();}}
 public static JSONArray models(String url,String secret,Jobs j)throws Exception{FilesEx.require(secret.length()>0,"E_AI_KEY: 请填写密钥或先保存密钥");HttpURLConnection c=(HttpURLConnection)new URL(ApiProtocol.modelsUrl(url)).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Bearer "+secret);c.setRequestProperty("User-Agent","P-Patcher/1.4.0");try{FilesEx.check(j);int code=c.getResponseCode();if(code<200||code>=300){InputStream e=c.getErrorStream();throw new IOException(ApiProtocol.error(code,e==null?"无错误正文":new String(FilesEx.read(e,32768),"UTF-8"),secret));}JSONObject r=new JSONObject(new String(FilesEx.read(c.getInputStream(),1048576),"UTF-8"));JSONArray a=r.optJSONArray("data");FilesEx.require(a!=null,"E_AI_MODELS: 此平台未提供标准模型列表，请手动填写模型 ID");JSONArray names=new JSONArray();for(int i=0;i<a.length()&&i<300;i++){String id=a.getJSONObject(i).optString("id");if(id.length()>0)names.put(id);}FilesEx.check(j);return names;}finally{c.disconnect();}}
}
